const articles = [];

for (const item of $input.all()) {
  const results = item.json.results || [];

  for (const article of results) {
    articles.push({
      title: article.title,
      url: article.url,
      summary: (article.content || "").substring(0, 300),
    });
  }
}

return [
  {
    json: {
      articles,
    },
  },
];

// Pull base64 image from the OpenAI Images API response; build the photo caption.
const resp = $input.first().json || {};
const b64 = resp && resp.data && resp.data[0] && resp.data[0].b64_json;
if (!b64) {
  throw new Error('OpenAI returned no image. Response: ' + JSON.stringify(resp).slice(0, 500));
}
const mime = 'image/png';  // gpt-image-1 returns PNG base64

// FALLBACK for Telegram's 1024-char caption limit: truncate-to-fit at a line/word
// boundary so the caption stays IDENTICAL to what the listener posts to LinkedIn.
let caption = String($('Loop Over Posts').item.json.post || '');
if (caption.length > 1024) {
  caption = caption.slice(0, 1020);
  const cut = Math.max(caption.lastIndexOf('\n'), caption.lastIndexOf(' '));
  if (cut > 800) caption = caption.slice(0, cut);
  caption = caption.trim() + '\u2026';
}
const ext = 'png';
return [{ json: { imageB64: b64, mime, ext, caption } }];
